import {getUser,getSettings,login,signup,logout,handleAuthCallback,requestPasswordRecovery,updateUser,oauthLogin,onAuthChange} from '@netlify/identity';
import {loadState,saveState,initialState,scenarios,stages,makeIncident,advance,csv} from './model.js';
import {inspectFrame,CuePersistence} from './detector.js';
import {Microphone,LocalCamera,canvasJPEG,loadImage} from './media.js';

const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',camera:'M3 7h12v12H3zM15 11l6-4v12l-6-4',fire:'M12 3c3 5 8 7 8 12a8 8 0 0 1-16 0c0-3 2-5 4-7 0 4 2 4 3 2Z',floor:'M3 3h18v18H3zM3 12h10V3M13 12h8',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v6l4 2',users:'M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M2 21v-4a5 5 0 0 1 10 0v4M16 4a4 4 0 0 1 0 8M16 15a5 5 0 0 1 6 5',mic:'M8 5a4 4 0 0 1 8 0v7a4 4 0 0 1-8 0ZM4 10v2a8 8 0 0 0 16 0v-2M12 20v3',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17v1',arrow:'M4 12h16M14 6l6 6-6 6',check:'m5 12 4 4L19 6',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10M12 1v3M12 20v3M1 12h3M20 12h3',sensor:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M5 5a10 10 0 0 0 0 14M19 5a10 10 0 0 1 0 14',close:'m5 5 14 14M19 5 5 19',play:'m8 4 12 8-12 8Z',menu:'M4 7h16M4 12h16M4 17h16',up:'M7 17 17 7M8 7h9v9',shield:'M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const brand=()=>`<a class="brand" href="/"><img src="/assets/firecam-logo.png" alt="">FireCam<span style="color:var(--accent)">.</span></a>`;
const button=(text,action,kind='',extra='')=>`<button type="button" class="${kind}" data-action="${action}" ${extra}>${text}</button>`;
const pill=(text,type='')=>`<span class="pill ${type}">${esc(text)}</span>`;
const date=t=>new Date(t).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'});
let storage;try{storage=localStorage;}catch{storage={getItem(){throw Error();},setItem(){throw Error();}};}
const loaded=loadState(storage);let state=loaded.data,warning=loaded.warning;
let view='',user=null,authSettings=null,authReady=false,authError='',recovery=false,menuOpen=false,afterLogin='',pendingScroll='';
const localDev=['localhost','127.0.0.1','[::1]'].includes(location.hostname);
let choice='fire',noResponse=true,activeId='',scenarioTimer=null,search='',filter='All',floor='Ground floor',historyFilter='All';
let opener,toastTimer,playTimer,playSeconds=0;
const recordings=[];
let key='',providerModels=[],connection='',aiController=null,aiImage='',lastFrame=null,persistence=new CuePersistence(),uploadGeneration=0;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5500);}
function persist(){if(!saveState(storage,state)){warning='Browser storage unavailable. Edits last only while this page is open.';toast(warning);}}
function micUpdate(text,level){if($('#mic-status'))$('#mic-status').textContent=text;if($('#level'))$('#level').style.width=`${Math.round(level*100)}%`;$('#ptt')?.classList.toggle('capturing',mic.active);}
const mic=new Microphone(micUpdate,item=>{recordings.push(item);if(view==='voice')renderRecordings();});
const camera=new LocalCamera(frame=>{
  const result=inspectFrame(frame,lastFrame);lastFrame=new Uint8ClampedArray(frame);
  const held=persistence.next(result);
  if($('#rule-result'))$('#rule-result').textContent=`${result.label}\n${result.detail}${held?'\nCue persisted for at least three checks. Human review required.':''}`;
},text=>{if($('#camera-status'))$('#camera-status').textContent=text;});
function pauseScenario(){clearInterval(scenarioTimer);scenarioTimer=null;}
function disconnect(){key='';providerModels=[];connection='';aiController?.abort();aiController=null;const el=$('#api-key');if(el)el.value='';}
function stopMedia(){$('#ptt')?.dispatchEvent(new Event('blur'));mic.stop();camera.stop();lastFrame=null;persistence=new CuePersistence();clearInterval(playTimer);playTimer=null;playSeconds=0;$('#sample-player')?.classList.remove('playing');uploadGeneration++;}
function closeDialog(){clearInterval(playTimer);playTimer=null;$('#dialog').close();$('#dialog').innerHTML='';opener?.focus();}
function dialog(title,body){opener=document.activeElement;$('#dialog').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">FIRECAM DEVELOPMENT DEMO</div><h2 id="dialog-title">${esc(title)}</h2></div>${button(icon('close'),'close','plain','aria-label="Close dialog"')}</div>${body}`;$('#dialog').showModal();}
function heading(eyebrow,title,text,actions=''){return `<div class="heading row between"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="muted">${text}</p></div>${actions}</div>`;}
const routes=[['dashboard','Overview','grid'],['scenarios','Incident simulator','fire'],['cameras','Cameras','camera'],['floor','Floor plan','floor'],['history','Alert history','clock'],['contacts','Emergency contacts','users'],['voice','Voice & recordings','mic'],['lab','Detection lab','sensor'],['settings','Settings','settings'],['help','Help & support','help']];
const navLink=([id,label,i])=>`<a href="#/${id}" class="nav-link ${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`;
function setMenu(open){menuOpen=open;document.querySelectorAll('#public-nav,.sidebar').forEach(e=>e.classList.toggle('open',open));document.querySelectorAll('.mobile-menu').forEach(b=>{b.setAttribute('aria-expanded',String(open));b.innerHTML=icon(open?'close':'menu');});}
const menuButton=()=>`<button type="button" class="mobile-menu plain" data-action="menu" aria-label="Toggle navigation" aria-expanded="${menuOpen}">${icon(menuOpen?'close':'menu')}</button>`;
function publicHeader(){return `<header class="container public-header row between">${brand()}<nav id="public-nav" class="${menuOpen?'open':''}" aria-label="Main navigation"><a href="#platform" data-scroll="platform">The platform</a><a href="#how" data-scroll="how">How it works</a><a href="#devices" data-scroll="devices">Across devices</a><a href="#/proposal">The proposal ${icon('up')}</a>${user?'':'<a class="nav-signin" href="#/login">Sign in</a>'}</nav><div class="row">${user?`<a class="button dark" href="#/dashboard">Open dashboard ${icon('arrow')}</a>`:`<a class="sign-in" href="#/login">Sign in</a><a class="button dark" href="#/register">Register ${icon('arrow')}</a>`}${menuButton()}</div></header>`;}
const faqs=[['How do I access the demo dashboard?','Register with your email and a password, confirm the email Netlify sends you, then sign in. The dashboard, incident simulator and detection lab open after you sign in.'],['Does this connect to real cameras?','No. Camera views are illustrative stills. The detection lab can use your own camera only after you press start, and nothing is recorded or uploaded.'],['Is FireCam actively detecting fires?','No. The lab has experimental colour-and-motion rules and an optional AI image review that you trigger yourself. Neither is a validated detector. Keep your certified smoke and fire alarms active.'],['Can I use it on Windows and mobile?','Yes. It runs in modern browsers and adapts to phone, tablet and desktop. No install is needed.'],['Where are accounts and data stored?','Accounts are managed by Netlify Identity. Demo changes (contacts, preferences, incidents) stay in your own browser. API keys for the optional AI review are kept in page memory only.']];
const privacyText='<p><strong>Account.</strong> Your email and password are handled by Netlify Identity. FireCam does not receive your password.</p><p><strong>Demo data.</strong> Sample incidents, contacts and preferences are stored only in this browser (localStorage).</p><p><strong>Camera, microphone, images.</strong> Used only on your device after you start them. An image leaves your browser only when you press Send image for review, and only to the provider you chose.</p><p><strong>API keys.</strong> Kept in page memory, sent through this site’s function to your chosen provider, and cleared when you leave the page.</p>';
function landing(){return `${publicHeader()}<main id="main"><section class="container hero"><div><div class="eyebrow">A NEW PERSPECTIVE ON HOME SAFETY</div><h1>A clearer view.<br>A <em>safer</em> space.</h1><p>Camera evidence. Sensor context. A thoughtful way to explore what happens after an alarm.</p><div class="row">${user?`<a href="#/dashboard" class="button primary">Open dashboard ${icon('arrow')}</a>`:`<a href="#/register" class="button primary">Register ${icon('arrow')}</a><a class="button" href="#/login">Sign in</a>`}</div><p style="margin-top:24px;font-size:11px">Development demo — no live monitoring or emergency calls.<br>${user?'You are signed in.':'Register with your email to open the demo dashboard.'}</p></div><div class="hero-image"><img src="/assets/hero.webp" alt="Illustrative modern home at dusk" width="1536" height="1024"><div class="floating row between"><div><strong>Everything. In view.</strong><br><small>One home. A little more context.</small></div>${pill('CONCEPT RESIDENCE','online')}</div></div></section><section class="strip"><div class="container row between"><span class="eyebrow">BUILT TO EXPLORE, NOT TO MONITOR</span><span>${icon('camera')} Camera evidence</span><span>${icon('sensor')} Sensor context</span><span>${icon('users')} Human review</span></div></section><section id="platform" class="container features"><article class="feature"><span class="number">01 / UNDERSTAND</span><h2>A home, with context.</h2><p class="muted">Explore illustrative camera views, room layouts and fictional contacts in one connected workspace.</p></article><article class="feature"><span class="number">02 / REHEARSE</span><h2>Follow the whole story.</h2><p class="muted">Replay fire, cooking vapour and missing-evidence scenarios. Every notification and handoff is simulated.</p></article><article class="feature"><span class="number">03 / EXPERIMENT</span><h2>Start small. Learn locally.</h2><p class="muted">Try local image rules without an API. Optionally review one image with your own AI key.</p><a href="${user?'#/lab':'#/register'}">${user?'Open the detection lab →':'Register to open the detection lab →'}</a></article></section>${landingSections()}${faqSection()}</main>${publicFooter()}`;}
function faqSection(){return `<section id="faq" class="container section"><div class="eyebrow">A LITTLE MORE CLARITY</div><h2>Good questions. Clear answers.</h2><div class="faq">${faqs.map(([q,a])=>`<details><summary>${esc(q)}</summary><p class="muted">${esc(a)}</p></details>`).join('')}</div><div class="row">${user?'<a class="button primary" href="#/dashboard">Open dashboard</a>':'<a class="button primary" href="#/register">Register to open the demo</a>'}</div></section>`;}
function publicFooter(){return `<footer class="container footer row between">${brand()}<small>Development showcase · Physical alarms remain essential.</small><span class="row"><a href="#/proposal">Project proposal</a><button type="button" class="plain" data-action="privacy">Privacy</button><a href="#/${user?'help':'register'}">${user?'Help & support':'Register'}</a></span></footer>`;}
function proposalPage(){return `${publicHeader()}<main id="main" class="container proposal-page"><div class="eyebrow">FIRECAM / PRODUCT & DELIVERY PROPOSAL</div><h1>A connected home.<br>A considered plan.</h1><p class="muted lead">An explorable concept for bringing camera evidence, sensor context and human review into one calm workspace — and an honest plan for what it would take to make it real.</p><div class="facts"><div><small>PLATFORM</small><strong>Web · Mobile · Windows browser</strong></div><div><small>DESIGN DIRECTION</small><strong>Clear, calm, spatial</strong></div><div><small>CURRENT RELEASE</small><strong>Development showcase + account sign-in</strong></div></div><section class="section"><div class="eyebrow">01 / DELIVERED EXPERIENCE</div><h2>From first impression to hands-on exploration.</h2><div class="features compact"><article class="feature"><h3>A complete product site</h3><p class="muted">Landing page, product story, FAQ and proposal, with registration and sign-in through Netlify Identity.</p></article><article class="feature"><h3>An interactive demo workspace</h3><p class="muted">Cameras, floor plan, alert history, emergency contacts, voice tools and three replayable incident scenarios, all on sample data.</p></article><article class="feature"><h3>A detection lab</h3><p class="muted">Free local colour-and-motion rules with no AI or API, plus an optional one-image review using your own key for OpenRouter, Gemini, Claude, OpenAI, Grok, Groq, Mistral or an OmniRoute gateway.</p></article></div></section><section class="section"><div class="eyebrow">02 / PATH TO LIVE MONITORING</div><h2>The next build stages.</h2><ol class="steps">${[['Connect the hardware','Choose camera protocols and sensors, and add a secure streaming gateway that reports genuine device status.'],['Validate detection','Evaluate a detection service against representative footage with defined thresholds, human review and failure states.'],['Deliver notifications','Integrate an approved SMS, email or push provider and test escalation with explicit operator control.'],['Prepare for deployment','Settle hosting, backups, retention, accessibility and security reviews on the target devices.']].map(([t,d],i)=>`<li><span class="number">0${i+1}</span><strong>${t}</strong><span class="muted">${d}</span>${pill('Planned')}</li>`).join('')}</ol></section><section class="section proposal"><div><div class="eyebrow">CLEAR BOUNDARIES</div><h2>Better decisions, honestly framed.</h2></div><div><p class="muted">Sample cameras, simulated alerts and the lab’s image rules are not evidence of active monitoring. Automated detection, physical sensor telemetry, background monitoring, emergency calling and outbound notifications are not connected.</p><p class="muted">No detection accuracy, response-time or safety-certification claims are made. Keep your certified fire alarms and emergency procedures in place.</p></div></section><div class="row" style="padding-bottom:64px">${user?'<a class="button primary" href="#/dashboard">Open dashboard</a>':'<a class="button primary" href="#/register">Register to open the demo</a><a class="button" href="#/login">Sign in</a>'}</div></main>${publicFooter()}`;}
const stepText=['A sample smoke or heat sensor raises an alarm.','Illustrative camera stills and sensor readings are gathered.','A scripted assessment — never a safety decision.','A simulated alert reaches the fictional homeowner.','The owner acknowledges, escalates or resolves it.','Every step is recorded in the alert history.'];
const field=(label,input)=>`<label class="field">${label}${input}</label>`;
function landingSections(){return `<section id="how" class="container section"><div class="eyebrow">HOW IT WORKS</div><h2>From alarm to understanding.</h2><p class="muted lead">Each scenario follows the same six stages. Everything is replayable, and nothing leaves your browser.</p><ol class="steps">${stages.map((s,i)=>`<li><span class="number">0${i+1}</span><strong>${esc(s)}</strong><span class="muted">${stepText[i]}</span></li>`).join('')}</ol><div class="row"><a class="button primary" href="${user?'#/scenarios':'#/register'}">${icon('play')} ${user?'Try an incident':'Register to try an incident'}</a></div></section><section id="devices" class="container section"><div class="eyebrow">ACROSS DEVICES</div><h2>One workspace, any screen.</h2><p class="muted lead">The showcase runs in any modern browser and adapts its layout to phone, tablet and desktop. No install is needed.</p><div class="features compact"><article class="feature"><span class="number">PHONE</span><h3>Check in anywhere.</h3><p class="muted">Review an alert and its evidence in a single focused column.</p></article><article class="feature"><span class="number">TABLET</span><h3>Walk the floor plan.</h3><p class="muted">Place devices and follow an incident room by room.</p></article><article class="feature"><span class="number">DESKTOP</span><h3>See the full picture.</h3><p class="muted">Cameras, history and the detection lab side by side.</p></article></div><div class="callout info">Planned, not connected: syncing history between devices and real push notifications. Demo changes stay in the browser you use.</div></section><section id="proposal" class="container section proposal"><div><div class="eyebrow">THE PROPOSAL</div><h2>A calm layer between an alarm and a decision.</h2><p class="muted lead">FireCam proposes bringing camera evidence, sensor context and human review into one place. This showcase is an early prototype of that idea.</p><ul class="points"><li><strong>Evidence first.</strong> Show what the cameras and sensors saw before anyone decides.</li><li><strong>People stay in charge.</strong> Assessments are advice for human review, never an automatic verdict.</li><li><strong>Honest by design.</strong> It is not a certified detector, and physical alarms stay essential.</li></ul></div><section class="panel" aria-labelledby="register-title"><h3 id="register-title">${user?'You’re signed in':'Register to open the dashboard'}</h3><p class="muted">${user?'Your dashboard is ready.':'Create an account with your email to explore the dashboard, incident simulator and detection lab.'}</p><div class="row">${user?'<a class="button primary" href="#/dashboard">Open dashboard</a>':'<a class="button primary" href="#/register">Register</a>'}</div></section></section>`;}
function shell(content){const who=user?(user.name||user.email||'Account'):'Local preview';return `<div class="shell"><aside class="sidebar ${menuOpen?'open':''}"><div class="side-head row between">${brand()}${menuButton()}</div><div class="side-body"><div class="workspace-picker">${icon('home')}<div><strong>${esc(state.preferences.home)}</strong><small>Demo workspace</small></div></div><div><div class="nav-label">WORKSPACE</div><nav aria-label="Workspace navigation">${routes.slice(0,8).map(navLink).join('')}</nav></div><div class="side-bottom"><div class="sidebar-note">${icon('shield')}<strong>A space to explore.</strong><p>Sample data. Real possibilities.</p><a href="#/proposal" class="small">About this demo →</a></div><nav aria-label="Settings and help">${routes.slice(8).map(navLink).join('')}</nav><div class="profile-chip"><span class="avatar" aria-hidden="true">${esc(who[0].toUpperCase())}</span><span class="who"><strong>${esc(who)}</strong><small>Demo member</small></span>${user?button('Sign out','logout','small'):''}</div></div></div></aside><div class="workspace"><header class="topbar"><span>${icon('home')} <strong>${esc(state.preferences.home)}</strong> <small> / Sample property</small></span><div class="row">${button(icon('sun'),'theme','plain','aria-label="Toggle light or dark mode"')}${user?`<a href="#/login">${esc(user.name||'Account')}</a>`:'<a href="#/login">Sign in</a>'}</div></header><div class="demo-banner">Development demo — no live monitoring or emergency calls <span id="network">${navigator.onLine?'':' · Offline: local features available'}</span></div><main id="main" class="workspace-main" tabindex="-1">${warning?`<div class="callout" role="status">${esc(warning)}</div>`:''}${content}</main></div></div>`;}
function cameraCard(c){return `<article class="camera">${button(`<div class="camera-img ${c.status==='Offline'?'offline':''}"><img src="/assets/${esc(c.image)}" alt="Illustrative ${esc(c.name)}" loading="lazy"><span class="tag">SAMPLE STILL · NO LIVE FEED</span></div><div class="camera-info"><div class="row between"><h3>${esc(c.name)}</h3>${pill(c.status,c.status==='Online'?'online':'warn')}</div><small>${esc(c.floor)} · ${esc(c.updated)}</small></div>`,'camera-detail','','data-id="'+c.id+'"')}</article>`;}
function eventRows(items){return items.length?items.slice(0,4).map(i=>`<div class="event-row"><span class="symbol warm">${icon('fire')}</span><div><strong>${esc(scenarios[i.kind].title)}</strong><small>${esc(scenarios[i.kind].room)} · ${date(i.time)}</small></div>${button('Review','incident','small',`data-id="${i.id}"`)}</div>`).join(''):'<p class="empty">No incidents. Run a sample scenario to explore the workflow.</p>';}
function dashboard(){return heading('YOUR HOME, AT A GLANCE','A little more peace of mind.','Explore the Morgan residence. All devices and readings below are sample data.',`<a class="button primary" href="#/scenarios">${icon('play')} Run a scenario</a>`)+`<div class="stats">${[['Cameras online','02 <small>/ 03</small>','Illustrative connectivity'],['Sample sensors','03','Smoke + heat'],['Needs review',String(state.incidents.filter(i=>i.status!=='Resolved').length).padStart(2,'0'),'Simulated incidents'],['Connected spaces','06','Across two floors']].map(([label,note,sub])=>`<div class="stat"><small>${label}</small><strong>${note}</strong><small>${sub}</small></div>`).join('')}</div><div class="row between section-label"><h2>Your spaces</h2><a href="#/cameras">View all devices →</a></div><div class="camera-grid">${state.devices.filter(d=>d.kind==='Camera').map(cameraCard).join('')}</div><div class="grid2" style="margin-top:26px"><section class="panel"><div class="row between"><h2>Recent activity</h2>${pill('SIMULATED')}</div>${eventRows(state.incidents)}<a href="#/history">Open alert history →</a></section><section class="panel"><div class="eyebrow">START HERE</div><h2 style="margin-top:13px">An alarm is only the beginning.</h2><p class="muted">Follow the evidence, review the assessment, and see how a simulated response reaches the homeowner.</p><a href="#/scenarios" class="button">Explore the workflow ${icon('arrow')}</a><div class="callout info">No physical alarm is connected or silenced.</div></section></div>`;}
function evidence(kind,id=''){return `<div class="evidence ${kind}" ${id?`id="${id}"`:''}><img src="/assets/${kind==='uncertain'?'bedroom':'kitchen'}.webp" alt="Illustrative ${kind==='fire'?'flame-like overlay':kind==='steam'?'vapour overlay':'obscured view'}; not recorded evidence"><span class="label">ILLUSTRATIVE SAMPLE · NOT ACTUAL FOOTAGE</span>${kind==='fire'?'<span class="cue" aria-hidden="true">🔥</span><span class="vapour" aria-hidden="true"></span>':kind==='steam'?'<span class="vapour" aria-hidden="true"></span>':''}</div>`;}
function incidentBody(i){const s=scenarios[i.kind];return `<div class="grid-even"><div>${evidence(s.evidence,'sample-player')}<div class="row between" style="margin-top:10px">${button(icon('play')+' Play illustration','play-sample','small')}<small id="sample-time">00:00 / 00:12 · animated still</small></div><small>Associated with ${esc(i.id)} · ${date(i.time)}</small></div><div><div class="eyebrow">${esc(state.preferences.home)} / ${s.room}</div><h2 style="margin-top:10px">${s.title}</h2>${pill(i.status,'warn')}<p style="margin-top:14px"><strong>Trigger:</strong> ${s.trigger}<br><strong>Sample temperature:</strong> ${s.temperature===null?'Unavailable':s.temperature+' °C'}<br><strong>Sample smoke:</strong> ${s.smoke}</p><div class="callout"><strong>Simulated assessment</strong><br>${s.reasoning}</div></div></div><ol class="timeline">${i.timeline.map(t=>`<li>${esc(t.text)}<small>${date(t.time)} · staged demo</small></li>`).join('')}</ol><div class="row">${i.status!=='Resolved'?button('Acknowledge','ack','',`data-id="${i.id}"`)+button('Resolve demo incident','resolve','primary',`data-id="${i.id}"`):pill('Demo review completed','online')}${button('Close','close')}</div>`;}
function simulator(){
  const current=state.incidents.find(i=>i.id===activeId);
  return heading('REPLAYABLE SCENARIOS','From alarm to understanding.','A deterministic walkthrough. No AI service, messages or emergency calls run here.')+`<div class="scenario-grid">${Object.entries(scenarios).map(([id,s],index)=>button(`<span class="eyebrow">SCENARIO 0${index+1}</span><b>${s.title}</b><small>${s.room} · ${s.trigger}</small>`,'choose','scenario-choice '+(choice===id?'selected':''),`data-id="${id}" aria-pressed="${choice===id}"`)).join('')}</div><section class="panel" style="margin-top:23px"><div class="row between"><div><h2>${scenarios[choice].title}</h2><label class="check"><input id="no-response" type="checkbox" ${noResponse?'checked':''} ${current?'disabled':''}>Simulate no response from the owner</label></div><div class="row">${button(scenarioTimer?'Pause':current&&current.step<5?'Continue':'Play scenario','scenario-play','primary')}${button('Next stage','scenario-step','',current?.step>=5?'disabled':'')}${button('Reset / replay','scenario-reset')}</div></div><div class="steps">${stages.map((s,n)=>`<div class="step ${current&&n<=current.step?'done':''}"><b>0${n+1}</b>${s}</div>`).join('')}</div>${current?`<div class="grid-even"><div>${evidence(choice)}<small>Illustration · ${esc(current.id)} · ${date(current.time)}</small></div><div><div class="eyebrow">CURRENT STAGE</div><h2>${stages[current.step]}</h2><p>${esc(current.timeline.at(-1).text)}</p>${current.step>=2?`<div class="callout">${scenarios[choice].reasoning}</div>`:''}${button('Open incident & timeline','incident','',`data-id="${current.id}"`)}</div></div>`:'<div class="empty">Choose a scenario and press Play. You can pause or step through each stage.</div>'}</section><div class="callout info">Fire-service escalation is a simulated monitoring-centre handoff. Police involvement would depend on additional circumstances and is not part of these fire-only scenarios.</div>`;
}
function ensureIncident(){let i=state.incidents.find(i=>i.id===activeId);if(!i){activeId='DEMO-'+crypto.randomUUID().slice(0,8);i=makeIncident(choice,activeId,new Date().toISOString(),noResponse);if(state.incidents.length>=100){toast('Demo history is full. Use Reset demo in Preferences to start again.');activeId='';return null;}state.incidents.unshift(i);persist();}return i;}
function tickScenario(){const i=ensureIncident();if(!i){pauseScenario();return;}advance(i,state.contacts);if(i.step>=5)pauseScenario();persist();render();}
function cameras(){const cameras=state.devices.filter(d=>d.kind==='Camera'&&(`${d.name} ${d.floor}`.toLowerCase().includes(search.toLowerCase()))&&(filter==='All'||d.status===filter));return heading('A VIEW INTO EVERY ROOM','Cameras & sensors.','Illustrative previews and sample connectivity. Nothing here is a remote live feed.')+`<div class="filters"><input id="camera-search" aria-label="Search cameras" placeholder="Search by room or floor…" value="${esc(search)}"><select id="camera-filter" aria-label="Filter camera status">${['All','Online','Offline'].map(v=>`<option ${filter===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="camera-grid">${cameras.length?cameras.map(cameraCard).join(''):'<p class="empty">No cameras match these filters.</p>'}</div><section class="panel" style="margin-top:24px"><h2>Sample sensor records</h2>${state.devices.filter(d=>d.kind!=='Camera').map(d=>`<div class="device-row"><span class="symbol">${icon('sensor')}</span><div><strong>${esc(d.name)}</strong><br><small>${esc(d.floor)} · ${esc(d.kind)} · ${esc(d.updated)}</small></div>${pill(d.status,d.status==='Online'?'online':'warn')}</div>`).join('')}</section>`;}
function floorPlan(){const rooms=floor==='Ground floor'?['Living room','Kitchen','Hallway']:['Bedroom','Study','Landing'];return heading('SPATIAL AWARENESS','Everything has its place.','Illustrative layout. Change a sample device’s floor to explore placement.')+`<div class="row" style="margin-bottom:20px">${['Ground floor','First floor'].map(f=>button(f,'floor',f===floor?'primary':'',`data-id="${f}"`)).join('')}</div><div class="grid2"><section class="panel"><div class="floor">${rooms.map(r=>`<div class="room"><b>${r}</b><div class="placement">${state.devices.filter(d=>d.floor===floor&&d.name.toLowerCase().startsWith(r.toLowerCase())).map(d=>pill(d.kind,d.status==='Online'?'online':'warn')).join('')}</div></div>`).join('')}</div><small>Diagram only · not a measured evacuation plan</small></section><section class="panel"><h2>Device placement</h2><form data-form="placement"><label class="field">Sample device<select name="device">${state.devices.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select></label><label class="field">Floor<select name="floor"><option>Ground floor</option><option>First floor</option></select></label><button class="primary">Save floor placement</button></form><p class="muted" style="margin-top:16px">Devices placed on a different floor appear in the floor’s unassigned area below.</p><div class="stack">${state.devices.filter(d=>d.floor===floor&&!rooms.some(r=>d.name.toLowerCase().startsWith(r.toLowerCase()))).map(d=>pill(d.name)).join('')}</div></section></div>`;}
function history(){const items=state.incidents.filter(i=>historyFilter==='All'||i.status===historyFilter);return heading('EVERY EVENT, WITH CONTEXT','Alert history.','Sample incidents and your local demo reviews.',button('Download demo CSV','export'))+`<div class="filters"><select id="history-filter" aria-label="Filter incidents">${['All','Active','Acknowledged','Resolved','Escalated (simulated)'].map(v=>`<option ${historyFilter===v?'selected':''}>${v}</option>`).join('')}</select></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Incident</th><th>Room</th><th>Time</th><th>Status</th><th>Action</th></tr></thead><tbody>${items.map(i=>`<tr><td>${scenarios[i.kind].title}<br><small>${i.id}</small></td><td>${scenarios[i.kind].room}</td><td>${date(i.time)}</td><td>${pill(i.status,i.status==='Resolved'?'online':'warn')}</td><td>${button('Review','incident','small',`data-id="${i.id}"`)}</td></tr>`).join('')}</tbody></table>${!items.length?'<p class="empty">No incidents match this filter.</p>':''}</div></section>`;}
function contacts(){return heading('THE PEOPLE WHO MATTER','Keep someone close.','Fictional contacts only. These edits stay in this browser and are never messaged.')+`<div class="grid-even">${state.contacts.map(c=>`<section class="panel"><div class="row between"><h2>${esc(c.role)}</h2>${icon('users')}</div><form data-form="contact" data-id="${c.id}"><label class="field">Fictional name<input name="name" required maxlength="100" value="${esc(c.name)}"></label><label class="field">Demo phone number / identifier<input name="phone" required maxlength="40" value="${esc(c.phone)}" pattern="DEMO-[A-Za-z0-9-]+" title="Use a fictional identifier beginning DEMO-, such as DEMO-OWNER-001"></label><p class="muted">Use DEMO- identifiers; real phone numbers are not needed.</p><button class="primary">Save contact</button></form></section>`).join('')}</div><div class="callout info">Response order: homeowner → backup contact → simulated monitoring-centre handoff. Nothing leaves the browser.</div>`;}
function recordingList(){return recordings.length?recordings.map(r=>`<article class="recording"><div class="row between"><strong>Local microphone recording</strong><small>${r.duration}s · ${date(r.time)}</small></div><audio controls src="${r.url}"></audio><div class="row"><a class="button small" href="${r.url}" download="firecam-local-audio-${r.id}.${r.type.includes('mp4')?'mp4':'webm'}">Download local audio</a>${button('Delete recording','delete-recording','small',`data-id="${r.id}"`)}</div></article>`).join(''):'<p class="empty">No microphone recordings yet. Record a short local test to try playback.</p>';}
function renderRecordings(){if($('#recordings'))$('#recordings').innerHTML=recordingList();}
function voice(){return heading('A VOICE, WITH CLEAR BOUNDARIES','Try the conversation.','Genuine microphone capture on this device. Audio is never sent to a camera, another person or an AI service.')+`<div class="grid-even"><section class="panel"><h2>Local microphone recorder</h2><div id="mic-status" class="status-line" role="status">Microphone off</div><div class="meter" role="img" aria-label="Live microphone level"><div id="level"></div></div><div class="row">${button('Start recording','record','primary')}${button('Stop microphone','mic-stop')}</div><div class="callout info">Maximum two minutes per recording. Recordings stay in memory until refresh or tab close. Download anything you want to keep.</div></section><section class="panel"><h2>Push-to-talk demonstration</h2><p class="muted">Hold the button, Space or Enter to capture locally. Release to stop. This does not create a recording or transmit audio.</p><button id="ptt" class="ptt">${icon('mic')} Hold to talk locally</button><small>Capture also stops on focus loss, navigation or hiding the tab.</small></section></div><section class="panel" style="margin-top:24px"><h2>Your local recordings</h2><div id="recordings">${recordingList()}</div></section><section class="panel" style="margin-top:24px"><h2>Illustrative incident media</h2><p class="muted">These are animated sample stills, separate from your actual microphone recordings.</p>${eventRows(state.incidents)}</section>`;}
function lab(){return heading('EXPERIMENTAL · HUMAN REVIEW REQUIRED','A closer look at the evidence.','Start with free local rules. Connect an AI provider only when you want a second, experimental interpretation.')+`<div class="grid-even"><section class="panel"><div class="row between"><h2>1. Local image rules</h2>${pill('NO AI · NO API','online')}</div><p class="muted">Checks orange/red pixels and changing grey regions. Three consecutive cues trigger a review notice. Steam, sunlight and movement can fool it.</p><div class="video-box"><video id="local-video" autoplay playsinline muted aria-label="Local camera preview"></video><img id="local-image" hidden alt="Your locally selected image"></div><p id="camera-status" class="status-line" role="status">Camera off · no background monitoring</p><div class="row">${button('Start local camera','camera-start','primary')}${button('Stop camera','camera-stop')}</div><label class="field" style="margin-top:18px">Or inspect a local image<input id="image-file" type="file" accept="image/jpeg,image/png,image/webp"></label><div id="rule-result" class="callout result" role="status">No image analysed. Nothing is monitoring your home.</div>${button('Use this frame for AI review','snapshot')}<small style="display:block;margin-top:12px">Snapshot preparation stays local. No upload happens until you press Send image for review.</small></section><section class="panel"><div class="row between"><h2>2. Optional AI review</h2>${pill('YOUR OWN KEY')}</div><p class="muted">One image per request. Keys stay in page memory, travel through this site’s Netlify function to your selected provider, and are cleared when you leave this page.</p>${!user?'<div class="callout">Sign in to connect a provider. <a href="#/login"><strong>Open sign in →</strong></a><br>The local detector remains available without an account.</div>':''}<form id="ai-form" data-form="connect"><label class="field">Provider<select id="provider" name="provider"><option value="openrouter">OpenRouter · choose a vision model</option><option value="gemini">Google Gemini · direct API</option><option value="anthropic">Anthropic Claude · direct API</option><option value="openai">OpenAI GPT · direct API</option><option value="xai">xAI Grok · direct API</option><option value="groq">Groq · Llama 4 vision</option><option value="mistral">Mistral · Pixtral & vision models</option><option value="omniroute">OmniRoute · your own AI gateway</option></select></label><label class="field" id="gateway-field" hidden>OmniRoute gateway URL<input id="gateway-url" name="gateway-url" type="url" autocomplete="off" spellcheck="false" maxlength="300" placeholder="https://your-omniroute-host/v1" ${!user?'disabled':''}></label><label class="check"><input id="free-only" type="checkbox" checked>Free options only (OpenRouter enforces zero-price :free models; other providers depend on your own account billing or gateway routing)</label><label class="field">API key<input id="api-key" type="password" autocomplete="off" spellcheck="false" placeholder="Paste your provider key for this session" required ${!user?'disabled':''}></label><div class="row"><button class="primary" ${!user?'disabled':''}>Connect & load models</button>${button('Disconnect','disconnect')}</div></form><p id="connection-status" class="status-line" role="status">Not connected</p><label class="field">Available image model<select id="ai-model" disabled><option>Connect to load current models</option></select></label><div id="ai-preview" class="empty">Prepare a snapshot on the left before sending.</div><label class="check"><input id="upload-consent" type="checkbox">Send this selected image to the chosen provider. I understand its data policies apply.</label><label class="check"><input id="billing-consent" type="checkbox">I checked provider billing and quota. Paid models and every provider except OpenRouter :free models may cost money.</label>${button('Send image for review','ai-review','primary',!user?'disabled':'')}<div id="ai-result" class="callout result" role="status">Provider output will appear here. It is never treated as an automatic safety decision.</div><div class="sources"><small>Get a key: <a href="https://openrouter.ai/settings/keys" target="_blank" rel="noopener noreferrer">OpenRouter</a> · <a href="https://aistudio.google.com/api-keys" target="_blank" rel="noopener noreferrer">Google AI Studio</a> · <a href="https://console.anthropic.com/settings/keys" target="_blank" rel="noopener noreferrer">Anthropic</a> · <a href="https://platform.openai.com/api-keys" target="_blank" rel="noopener noreferrer">OpenAI</a> · <a href="https://console.x.ai" target="_blank" rel="noopener noreferrer">xAI</a> · <a href="https://console.groq.com/keys" target="_blank" rel="noopener noreferrer">Groq</a> · <a href="https://console.mistral.ai/api-keys" target="_blank" rel="noopener noreferrer">Mistral</a> · <a href="https://github.com/diegosouzapw/OmniRoute" target="_blank" rel="noopener noreferrer">OmniRoute</a> (Dashboard → Endpoints; the gateway must be reachable over public HTTPS)<br>AI chat subscriptions do not supply API credit. Free models have quotas and availability can change.</small></div></section></div><div class="callout">Neither image rules nor general-purpose AI are validated fire-alarm systems. No detected cue means safety is unknown. Keep physical alarms active; this lab never controls them.</div>`;}
function settings(){return heading('MAKE YOURSELF AT HOME','A few personal touches.','Non-sensitive demo preferences are saved only in this browser.')+`<div class="grid-even"><section class="panel"><h2>Workspace preferences</h2><form data-form="preferences"><label class="field">Fictional display name<input name="name" value="${esc(state.preferences.name)}" required maxlength="100"></label><label class="field">Sample home name<input name="home" value="${esc(state.preferences.home)}" required maxlength="100"></label><label class="field">Theme<select name="theme"><option value="light" ${state.preferences.theme==='light'?'selected':''}>Warm light</option><option value="dark" ${state.preferences.theme==='dark'?'selected':''}>Evening dark</option></select></label><button class="primary">Save preferences</button></form></section><section class="panel"><h2>A clean slate.</h2><p class="muted">Reset sample incidents, contacts, device placement and preferences. Local microphone recordings and session AI keys are also cleared. Your managed login account is retained.</p>${button('Reset demo…','reset','')}<div class="callout info">You will be asked to confirm before demo data or recordings are removed.</div></section></div>`;}
function help(){return heading('FUNCTIONAL, SIMULATED, PLANNED','A little more clarity.','Know exactly what this development showcase does.')+`<div class="grid-even"><section class="panel"><h2>Functional on this device</h2><p>Camera search, sample device placement, contact editing, preferences, CSV export, microphone recording/playback/download and local image checks. Your demo changes remain in this browser, shared by anyone using this browser profile.</p><h2>Functional when connected</h2><p>Netlify Identity signup, login and password recovery, plus authenticated one-image reviews using your own OpenRouter, Gemini, Anthropic, OpenAI, xAI, Groq or Mistral key, or your OmniRoute gateway. Provider reviews are real external requests; the incident simulator never calls them.</p><h2>Simulated</h2><p>All home sensors, sample cameras, notifications, acknowledgements and monitoring-centre handoffs. Evidence illustrations are animated stills, not real incident recordings. Scenario assessments are scripted, with no confidence percentages.</p></section><section class="panel"><h2>Planned, not connected</h2><p>Remote security cameras, certified detection, physical sensors, multi-device history, real notifications, monitoring-centre services and remote two-way audio. No pre-event recording, background monitoring or emergency calls are active.</p><h2>Beginner recommendation</h2><p>Explore the deterministic scenarios first, then the local detection lab. Treat colour-and-motion rules as a programming experiment. Optional AI can help describe evidence but cannot establish safety.</p><h2>Storage & privacy</h2><p>Demo records use versioned localStorage. Actual images, API keys and microphone recordings are not stored there. Audio stays local. AI images are sent only after your explicit action and consent. Provider free-tier data policies may allow product improvement.</p></section></div><section class="panel sources" style="margin-top:24px"><h2>Provider options & sources</h2><p><a href="https://openrouter.ai/docs/guides/routing/model-variants/free" target="_blank" rel="noopener noreferrer">OpenRouter free variants</a>: choose a currently available vision-capable :free model; paid models are opt-in. <a href="https://ai.google.dev/gemini-api/docs/pricing" target="_blank" rel="noopener noreferrer">Gemini pricing</a>: Flash-Lite is the cost-conscious starting option; project quota and billing determine actual charges. No provider is universally the “best” detector.</p><p><a href="https://ai.google.dev/gemini-api/docs/image-understanding" target="_blank" rel="noopener noreferrer">Gemini image understanding</a> · <a href="https://openrouter.ai/docs/api/reference/limits" target="_blank" rel="noopener noreferrer">OpenRouter limits</a></p><small>Assets reused from the existing FireCam project: user-provided logo, generated concept home, Unsplash sample interiors and Manrope (SIL OFL). Full provenance is in the project documentation.</small></section>`;}
function authPage(){return `<header class="container public-header row between">${brand()}<a href="#/">← Back to home</a></header><main id="main" class="panel auth">${user&&!recovery?`<div class="eyebrow">MANAGED ACCOUNT</div><h1>You’re signed in.</h1><p>${esc(user.email)}</p><p class="muted">Your account opens the demo dashboard. Demo records remain browser-local and are not private account storage.</p><div class="row"><a class="button primary" href="#/dashboard">Open dashboard</a>${button('Sign out','logout')}</div>`:`<div class="eyebrow">WELCOME TO FIRECAM</div><h1>${recovery?'Set a new password.':view==='register'?'Make yourself at home.':'Good to see you.'}</h1><p class="muted">${recovery?'Choose a new password for your account.':view==='register'?'Create your account to open the demo dashboard.':'Sign in to open the demo dashboard.'} Accounts are managed by Netlify Identity.</p>${!authReady?'<p role="status">Checking login availability…</p>':!authSettings?`<div class="callout">${esc(authError||'Login is not configured. Enable Identity in the Netlify project dashboard.')}</div>`:''}<form data-form="${recovery?'recover':view==='register'?'register':'login'}">${!recovery?'<label class="field">Email<input name="email" type="email" autocomplete="email" required maxlength="200"></label>':''}<label class="field">${recovery?'New password':'Password'}<input name="password" type="password" autocomplete="${view==='register'||recovery?'new-password':'current-password'}" minlength="12" maxlength="128" required></label>${view==='register'?'<small>Use at least 12 characters. Check your email to confirm your account.</small>':''}<div class="error" id="auth-error" role="alert"></div><p id="auth-notice" class="notice" role="status"></p><button class="primary" ${!authSettings||view==='register'&&authSettings.disableSignup?'disabled':''}>${recovery?'Save new password':view==='register'?'Create account':'Sign in'}</button></form>${!recovery?`<div class="row" style="margin-top:20px"><a href="#/${view==='register'?'login':'register'}">${view==='register'?'Already have an account?':'Create an account'}</a>${button('Forgot password?','forgot','plain')}</div>${authSettings?Object.entries(authSettings.providers||{}).filter(([name,enabled])=>enabled&&name!=='email').map(([name])=>button('Continue with '+name,'oauth','',`data-id="${esc(name)}"`)).join(''):''}`:''}`}<div class="callout info">Development demo — no live monitoring or emergency calls.</div></main>`;}
const pages=Object.assign(Object.create(null),{dashboard,scenarios:simulator,cameras,floor:floorPlan,history,contacts,voice,lab,settings,help});
// The workspace is for registered users. This is a client-side gate for sample data only;
// the AI function enforces its own login check on the server.
function render(){
  document.documentElement.dataset.theme=state.preferences.theme;
  if(pages[view]&&!user&&!(localDev&&authReady&&!authSettings)){
    if(!authReady){$('#app').innerHTML='<main id="main" class="loading" role="status">Checking your account…</main>';return;}
    afterLogin=view;location.hash='/login';return;
  }
  $('#app').innerHTML=view==='login'||view==='register'?authPage():view==='proposal'?proposalPage():pages[view]?shell(pages[view]()):landing();
  if(view==='voice')wirePTT();
}
function route(){
  stopMedia();pauseScenario();disconnect();aiImage='';menuOpen=false;if($('#dialog').open)closeDialog();
  const routeHash=location.hash.replace(/^#\/?/,'').split('?')[0];
  view=routeHash||location.pathname.replace(/^\/|\/$/g,'');
  render();
  if(pendingScroll){const id=pendingScroll;pendingScroll='';requestAnimationFrame(()=>document.getElementById(id)?.scrollIntoView());}else window.scrollTo(0,0);
  $('#main')?.focus({preventScroll:true});
}
function wirePTT(){
  const el=$('#ptt');let held=false;
  const start=()=>{if(held)return;held=true;mic.start(false).catch(e=>toast(e.message));};
  const stop=()=>{if(!held)return;held=false;mic.stop();};
  el.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();el.setPointerCapture(e.pointerId);start();});
  for(const event of ['pointerup','pointercancel','lostpointercapture','blur'])el.addEventListener(event,stop);
  el.addEventListener('keydown',e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();if(!e.repeat)start();}});
  el.addEventListener('keyup',e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();stop();}});
}
async function providerRequest(body){
  if(aiController)throw Error('A provider request is already running.');
  const controller=new AbortController();aiController=controller;const timeout=setTimeout(()=>controller.abort(),45000);
  try{const r=await fetch('/.netlify/functions/ai',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(body),signal:controller.signal});const b=await r.json().catch(()=>({error:'AI functions require a Netlify deployment.'}));if(!r.ok)throw Error(b.error||'Request unavailable.');return b;}finally{clearTimeout(timeout);if(aiController===controller)aiController=null;}
}
function confirmation(title,text,action,id=''){dialog(title,`<p>${text}</p><div class="row">${button('Cancel','close')}${button('Confirm','confirm-'+action,'primary',`data-id="${esc(id)}"`)}</div>`);}
document.addEventListener('click',e=>{
  const link=e.target.closest('a[data-scroll]');if(!link)return;e.preventDefault();setMenu(false);
  const section=document.getElementById(link.dataset.scroll);
  if(section)section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});
  else{pendingScroll=link.dataset.scroll;location.hash='/';}
});
document.addEventListener('click',async e=>{
  const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id;
  try{
    if(action==='close')return closeDialog();
    if(action==='menu')return setMenu(!menuOpen);
    if(action==='privacy')return dialog('Privacy',privacyText);
    if(action==='theme'){state.preferences.theme=state.preferences.theme==='light'?'dark':'light';persist();document.documentElement.dataset.theme=state.preferences.theme;return;}
    if(action==='choose'){pauseScenario();choice=id;activeId='';render();}
    if(action==='scenario-play'){
      if(scenarioTimer){pauseScenario();render();return;}
      const i=ensureIncident();if(!i)return;if(i.step>=5){toast('Use Reset / replay to restart this incident.');return;}
      scenarioTimer=setInterval(tickScenario,1800);render();
    }
    if(action==='scenario-step'){pauseScenario();tickScenario();}
    if(action==='scenario-reset'){pauseScenario();const i=state.incidents.find(i=>i.id===activeId);if(i)confirmation('Reset this scenario?','This replaces the staged timeline for this demo incident. Other incidents remain.','scenario-reset',i.id);else{activeId='';render();}}
    if(action==='confirm-scenario-reset'){const index=state.incidents.findIndex(i=>i.id===id);if(index>=0)state.incidents[index]=makeIncident(choice,id,new Date().toISOString(),noResponse);persist();closeDialog();render();}
    if(action==='incident'){const i=state.incidents.find(i=>i.id===id);if(i){pauseScenario();dialog('Incident review · simulated',incidentBody(i));}}
    if(action==='ack'||action==='resolve'){
      const i=state.incidents.find(i=>i.id===id);if(i&&i.status!=='Resolved'){i.acknowledged=true;i.status=action==='ack'?'Acknowledged':'Resolved';i.timeline.push({time:new Date().toISOString(),text:action==='ack'?'User acknowledged this simulated incident':'User resolved this simulated incident; no physical alarm changed'});i.timeline=i.timeline.slice(-30);persist();closeDialog();render();toast('Demo incident updated.');}
    }
    if(action==='camera-detail'){const c=state.devices.find(d=>d.id===id);dialog(c.name,`<div class="evidence"><img src="/assets/${c.image}" alt="Illustrative ${esc(c.name)}"><span class="label">SAMPLE STILL · NO LIVE CONNECTION</span></div><p style="margin-top:16px">${esc(c.floor)} · ${esc(c.updated)}</p><div class="callout info">This is a bundled illustrative image. Use the detection lab for an on-demand local camera experiment.</div><a class="button primary" href="#/lab">Open detection lab</a>`);}
    if(action==='floor'){floor=id;render();}
    if(action==='export'){const blob=new Blob([csv(state.incidents)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='firecam-DEMO-data.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
    if(action==='record'){document.querySelectorAll('audio').forEach(a=>a.pause());await mic.start(true);}
    if(action==='mic-stop')mic.stop();
    if(action==='delete-recording')confirmation('Delete local recording?','This discards the selected in-memory audio recording. Download it first if you want a copy.','recording',id);
    if(action==='confirm-recording'){const index=recordings.findIndex(r=>r.id===id);if(index>=0){URL.revokeObjectURL(recordings[index].url);recordings.splice(index,1);}closeDialog();renderRecordings();}
    if(action==='reset')confirmation('Reset all demo data?','This replaces local sample edits and clears in-memory recordings and AI keys. Your managed account is retained.','reset');
    if(action==='confirm-reset'){mic.discardPending();stopMedia();disconnect();recordings.forEach(r=>URL.revokeObjectURL(r.url));recordings.length=0;state=initialState();choice='fire';noResponse=true;activeId='';search='';filter='All';floor='Ground floor';historyFilter='All';aiImage='';warning='';persist();closeDialog();render();toast('Demo reset.');}
    if(action==='camera-start'){lastFrame=null;persistence=new CuePersistence();$('#local-image').hidden=true;$('#local-video').hidden=false;try{await camera.start($('#local-video'));}catch(error){camera.stop();throw error;}}
    if(action==='camera-stop')camera.stop();
    if(action==='snapshot'){
      const source=$('#local-image').hidden?$('#local-video'):$('#local-image');
      aiImage=canvasJPEG(source);$('#ai-preview').innerHTML=`<img src="${aiImage}" alt="Selected image to send for review" style="max-width:100%;max-height:160px"><p>Selected snapshot · not yet uploaded</p>`;$('#upload-consent').checked=false;
    }
    if(action==='disconnect'){disconnect();$('#connection-status').textContent='Disconnected · key cleared';$('#ai-model').innerHTML='<option>Connect to load models</option>';$('#ai-model').disabled=true;}
    if(action==='ai-review'){
      if(!key||!connection)throw Error('Connect a provider first.');if(!aiImage)throw Error('Prepare a snapshot first.');if(!$('#upload-consent').checked)throw Error('Confirm sending this selected image first.');
      const provider=$('#provider').value,freeOnly=$('#free-only').checked;
      if((provider!=='openrouter'||!freeOnly)&&!$('#billing-consent').checked)throw Error('Check and confirm provider billing before sending.');
      $('#ai-result').textContent='Reviewing the selected image…';target.disabled=true;
      try{const response=await providerRequest({action:'review',provider,key,freeOnly,baseUrl:$('#gateway-url').value.trim(),model:$('#ai-model').value,image:aiImage,consent:true,paidConsent:$('#billing-consent').checked,billingConfirmed:$('#billing-consent').checked});if(view==='lab'&&$('#ai-result'))$('#ai-result').textContent=`Experimental ${response.provider} review · ${response.model}\n\n${response.text}\n\nThis output is unverified and does not determine safety.`;}
      catch(error){if($('#ai-result'))$('#ai-result').textContent=`Review unavailable: ${error.message}. Safety remains unknown.`;}
      finally{if(target.isConnected)target.disabled=false;}
    }
    if(action==='logout'){stopMedia();disconnect();await logout();user=null;afterLogin='';if(location.hash==='#/')render();else location.hash='/';}
    if(action==='forgot'){const email=$('[name=email]')?.value;if(!email)throw Error('Enter your account email first.');await requestPasswordRecovery(email);toast('If this account is eligible, a recovery email will arrive.');}
    if(action==='oauth')oauthLogin(id);
    if(action==='play-sample'){
      clearInterval(playTimer);playSeconds=0;$('#sample-player').classList.add('playing');$('#sample-time').textContent='00:00 / 00:12 · animated still';
      playTimer=setInterval(()=>{playSeconds++;$('#sample-time').textContent=`00:${String(playSeconds).padStart(2,'0')} / 00:12 · animated still`;if(playSeconds>=12){clearInterval(playTimer);playTimer=null;$('#sample-player').classList.remove('playing');}},1000);
    }
  }catch(error){toast(error.message||'This action is unavailable.');}
});
document.addEventListener('submit',async e=>{
  const form=e.target.closest('form');if(!form)return;e.preventDefault();const values=Object.fromEntries(new FormData(form)),kind=form.dataset.form,submit=form.querySelector('button[type=submit],button:not([type])');
  if(submit)submit.disabled=true;
  try{
    if(kind==='contact'){const c=state.contacts.find(c=>c.id===form.dataset.id);c.name=values.name.trim();c.phone=values.phone.trim();persist();toast('Fictional contact saved in this browser.');}
    if(kind==='preferences'){state.preferences={name:values.name.trim(),home:values.home.trim(),theme:values.theme};persist();render();toast('Preferences saved.');}
    if(kind==='placement'){state.devices.find(d=>d.id===values.device).floor=values.floor;persist();render();toast('Sample placement updated.');}
    if(kind==='login'){await login(values.email,values.password);user=await getUser();form.reset();const next=afterLogin||'dashboard';afterLogin='';location.hash='/'+next;}
    if(kind==='register'){await signup(values.email,values.password);form.reset();user=await getUser();if(user){afterLogin='';location.hash='/dashboard';}else{$('#auth-error').textContent='';$('#auth-notice').textContent='Almost there. Check your email and confirm your account, then sign in to open the demo dashboard.';}}
    if(kind==='recover'){await updateUser({password:values.password});recovery=false;form.reset();user=await getUser();render();toast('Password updated.');}
    if(kind==='connect'){
      const provider=values.provider,freeOnly=$('#free-only').checked;
      key=values['api-key']||$('#api-key').value.trim();connection='';$('#api-key').value='';$('#connection-status').textContent='Checking key and available models…';
      try{const result=await providerRequest({action:'models',provider,key,freeOnly,baseUrl:(values['gateway-url']||'').trim()});if(view!=='lab'||!key)return;providerModels=result.models;connection=provider;$('#ai-model').innerHTML=providerModels.length?providerModels.map(m=>`<option value="${esc(m.id)}">${esc(m.name)}${m.free?' · free option':provider==='openrouter'?' · paid':' · billed by your account'}</option>`).join(''):'<option>No matching image models available</option>';$('#ai-model').disabled=!providerModels.length;$('#connection-status').textContent=providerModels.length?'Connected · key kept only in page memory':'Key verified; no eligible models currently available.';}
      catch(error){key='';connection='';if($('#connection-status'))$('#connection-status').textContent='Connection failed · key cleared';throw error;}
    }
  }catch(error){if($('#auth-error'))$('#auth-error').textContent=error.message;else toast(error.message||'Could not complete this action.');}
  finally{if(submit?.isConnected)submit.disabled=false;}
});
document.addEventListener('input',e=>{if(e.target.id==='camera-search'){search=e.target.value;const pos=e.target.selectionStart;render();$('#camera-search').focus();$('#camera-search').setSelectionRange(pos,pos);}});
document.addEventListener('change',async e=>{
  if(e.target.id==='camera-filter'){filter=e.target.value;render();}
  if(e.target.id==='history-filter'){historyFilter=e.target.value;render();}
  if(e.target.id==='no-response')noResponse=e.target.checked;
  if(e.target.id==='provider'){const gateway=e.target.value==='omniroute';$('#gateway-field').hidden=!gateway;$('#gateway-url').required=gateway;}
  if(e.target.id==='provider'||e.target.id==='free-only'){disconnect();$('#ai-model').disabled=true;$('#ai-model').innerHTML='<option>Reconnect after changing provider or cost setting</option>';$('#connection-status').textContent='Disconnected · reconnect to refresh models';$('#billing-consent').checked=false;}
  if(e.target.id==='image-file'){
    const file=e.target.files?.[0];if(!file)return;camera.stop();lastFrame=null;const generation=++uploadGeneration;
    try{const img=await loadImage(file);if(generation!==uploadGeneration||view!=='lab')return;const jpeg=canvasJPEG(img);$('#local-image').src=jpeg;$('#local-image').hidden=false;$('#local-video').hidden=true;const c=document.createElement('canvas');c.width=160;c.height=120;const ctx=c.getContext('2d');ctx.drawImage(img,0,0,160,120);const result=inspectFrame(ctx.getImageData(0,0,160,120).data);$('#rule-result').textContent=result.label+'\n'+result.detail;aiImage='';$('#ai-preview').textContent='Use this frame for AI review to select the new image.';}catch(error){toast(error.message);}
  }
});
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
window.addEventListener('hashchange',route);
window.addEventListener('blur',()=>{stopMedia();pauseScenario();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopMedia();pauseScenario();}});
window.addEventListener('pagehide',()=>{stopMedia();disconnect();});
for(const event of ['online','offline'])window.addEventListener(event,()=>{if($('#network'))$('#network').textContent=navigator.onLine?'':' · Offline: local features available';});
onAuthChange(async event=>{if(event==='logout'){user=null;disconnect();render();}});
async function boot(){
  route();
  try{
    const callback=await handleAuthCallback();if(callback?.type==='recovery'){recovery=true;view='login';}
    user=await getUser();authSettings=await getSettings();
  }catch{authError='Managed login is unavailable here. On Netlify, enable Identity in the project dashboard. Local previews on localhost skip the login.';}
  authReady=true;
  stopMedia();render();
}
boot();
